package ais.action.master.sosial.helper;
import java.math.BigDecimal; import java.text.NumberFormat; import java.util.Locale;
public final class SocialHtml { private SocialHtml(){} public static String e(Object value){if(value==null)return "";String s=String.valueOf(value);return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");} public static String money(BigDecimal value){if(value==null)value=BigDecimal.ZERO;NumberFormat f=NumberFormat.getCurrencyInstance(new Locale("id","ID"));f.setMaximumFractionDigits(0);return f.format(value);} public static int progress(BigDecimal value,BigDecimal target){if(value==null||target==null||target.signum()<=0)return 0;int p=value.multiply(new BigDecimal("100")).divide(target,0,BigDecimal.ROUND_DOWN).intValue();return Math.max(0,Math.min(100,p));} }
